import json

def transform(grid):
    """Output is 3×2 grid of input tiles arranged as:
    vhflip  vflip
    hflip   identity
    vhflip  vflip
    """
    if not grid or not grid[0]:
        return grid

    H, W = len(grid), len(grid[0])

    def identity(g): return json.loads(json.dumps(g))
    def hflip(g): return [row[::-1] for row in g]
    def vflip(g): return g[::-1]
    def vhflip(g): return vflip(hflip(g))

    # Build output row by row
    out = []
    for r_out in range(3):  # 3 rows of tiles
        out_row = []
        for c_out in range(2):  # 2 tiles per row
            # Select the tile
            if r_out == 0:
                if c_out == 0: piece = vhflip(grid)
                else: piece = vflip(grid)
            elif r_out == 1:
                if c_out == 0: piece = hflip(grid)
                else: piece = identity(grid)
            else:
                piece = vflip(grid)
            out_row.append(piece)

        # Now interleave columns of tiles
        for row_idx in range(H):  # Each tile has H rows
            compiled_row = []
            for tile in out_row:
                compiled_row.extend(tile[row_idx])
            out.append(compiled_row)

    return out

